Verification Results", "fields": [{"id": "swabs", "rows": {"mode": "dynamic", "addLabel": "Add result"}, "type": "grid", "label": "Results", "columns": [{"id": "area_surface", "type": "text", "label": "Area / surface tested", "width": 3, "required": true, "pickFromTable": {"fill": {"method": "Method", "accept_limit": "Acceptable limit / standard"}, "table": "schedule_ref"}}, {"id": "method", "type": "select", "label": "Method", "width": 2, "options": ["ATP swab", "Microbiological swab", "Allergen swab", "Visual"], "required": true}, {"id": "result_reading", "type": "text", "label": "Result / reading", "width": 2}, {"id": "accept_limit", "type": "text", "label": "Acceptable limit", "width": 2}, {"id": "pass_fail", "type": "pass_fail", "label": "Pass / fail", "width": 1, "required": true}, {"id": "corrective_action", "type": "text", "label": "Corrective action", "width": 3}, {"id": "retest_result", "type": "text", "label": "Re-test result", "width": 2}, {"id": "verified_by", "type": "text", "label": "Verified by", "width": 2}]}], "description": "Record each verification result against its limit. On a Fail, re-clean, re-test, and record the re-test result. Add a row per surface tested."}, {"id": "review", "title": "Review", "fields": [{"id": "reviewed_by", "role": "verifier", "type": "signature", "label": "Reviewed by (SQF Practitioner)", "width": "half", "statement": "I reviewed these verification results for trends and program effectiveness."}, {"id": "review_date", "type": "date", "label": "Date", "width": "half"}]}], "settings": {"deletable": false, "attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "{verification_date} — Sanitation verification"}, "schemaVersion": 1}, "revision_history": "New - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
