update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-601_Label_Review_Approval_Form.docx", "path": "0a1b9e92-8857-49b4-ac8f-20ec9fa9f105/files/FRM-601_Label_Review_Approval_Form.docx"}, {"name": "FRM-601_Label_Review_Approval_Form.pdf", "path": "0a1b9e92-8857-49b4-ac8f-20ec9fa9f105/files/FRM-601_Label_Review_Approval_Form.pdf"}], "form_schema": {"sections": [{"id": "section_1", "title": "Section 1 — Product & Label Identification", "fields": [{"id": "product_name", "type": "text", "label": "Product Name", "width": "half", "required": true, "showInList": true, "suggestFrom": {"form": "FRM-501", "field": "product_name", "drafts": true}}, {"id": "sku_item_no", "type": "text", "label": "SKU / Item No.", "width": "half"}, {"id": "label_artwork_version", "type": "text", "label": "Label / Artwork Version", "width": "third", "showInList": true}, {"id": "linked_formula_version", "type": "text", "label": "Linked Formula Version", "width": "third", "suggestFrom": {"form": "FRM-501", "field": "formula_version", "match": {"to": "product_name", "field": "product_name"}, "drafts": true}}, {"id": "date", "type": "date", "label": "Date", "width": "third", "defaultToday": true}, {"id": "customer_brand", "type": "text", "label": "Customer / Brand", "suggestFrom": {"form": "FRM-011", "grid": "contacts", "field": "_label", "where": {"column": "group", "equals": "Customer (brand owner)"}, "drafts": true, "current": true}}, {"id": "label_name", "type": "text", "label": "Label Name", "width": "half", "showInList": true}, {"id": "barcode_number", "help": "The number printed under the bar code on this label, digits only. Leave blank if the label carries no bar code. The first-pack check on the Production Lot Record (FRM-520) compares the pack with this number.", "type": "text", "label": "Bar code number", "width": "half", "maxLength": 20}]}, {"id": "section_2", "title": "Section 2 — Change Details", "fields": [{"id": "change_details_info", "text": "Complete this section only if this Label Review & Approval applies to a change to an existing, previously approved label.", "type": "info", "label": "Change Details Instructions"}, {"id": "supersedes_version", "type": "text", "label": "Supersedes Version"}, {"id": "reason_for_change", "type": "text", "label": "Reason for Change"}, {"id": "description_of_change", "type": "textarea", "label": "Description of Change"}]}, {"id": "section_3", "title": "Section 3 — Line-by-Line Label Verification", "fields": [{"id": "label_verification_grid", "rows": {"mode": "fixed", "labels": ["Statement of Identity / Product Name (Common or usual name present and correctly placed (21 CFR 101.3).)", "Net Quantity of Contents (Net weight / count accurate, dual declaration, correct placement (21 CFR 101.7 / 101.105).)", "Ingredient Statement (Complete, accurate, listed in descending order of predominance, and matches the approved formula (21 CFR 101.4).)", "Allergen Declaration (All major allergens declared; “Contains” / advisory statements correct (FALCPA / 21 CFR 101).)", "Nutrition Facts Panel (Format, serving size, values, and rounding compliant (21 CFR 101.9).)", "Manufacturer / Distributor (Name and full address of manufacturer, packer, or distributor present (21 CFR 101.5).)", "Country of Origin (Declared where required.)", "Lot / Date Coding (Lot and date code scheme and placement defined and legible.)", "Claims & Certifications (All claims substantiated; certification marks authorized and correct.)", "21 CFR §101 Formatting (Type size, prominence, panel placement, and language compliant.)", "Customer-Specified Elements (Artwork, logos, copy, and customer requirements match the approved brief.)"]}, "type": "grid", "label": "Label Verification", "columns": [{"id": "pass_fail_na", "type": "select", "label": "Pass / Fail / NA", "options": ["Pass", "Fail", "NA"]}, {"id": "reviewer_notes", "type": "text", "label": "Reviewer Notes"}]}]}, {"id": "section_4", "title": "Section 4 — Customer Label Approval", "fields": [{"id": "customer_approval_info", "text": "Customer-designed or customer-specified labels must be approved by the customer; records retained (SQF 2.3.2.3).", "type": "info", "label": "Customer Approval Instructions"}, {"id": "customer_approval_required", "type": "select", "label": "Customer approval required?", "options": ["Yes", "No (internal/company label)"]}, {"id": "approval_evidence", "type": "select", "label": "Approval evidence (check one):", "options": ["Signed approval", "Archived email confirmation"]}, {"id": "customer_approver_name_title", "type": "text", "label": "Customer Approver Name / Title"}, {"id": "approval_reference", "type": "text", "label": "Approval Reference (email ID / doc)", "width": "half"}, {"id": "approval_date", "type": "date", "label": "Approval Date", "width": "half"}]}, {"id": "section_5", "title": "Section 5 — QA Authorization & Controlled File", "fields": [{"id": "qa_qc_authorization_info", "text": "The SQF Practitioner must authorize the label before release. File the approved label in the Controlled Label File.", "type": "info", "label": "QA Authorization Instructions"}, {"id": "reviewed_by", "type": "text", "label": "Reviewed By", "width": "third"}, {"id": "reviewed_by_signature", "role": "filler", "type": "signature", "label": "Signature", "width": "third"}, {"id": "reviewed_by_date", "type": "date", "label": "Date", "width": "third"}, {"id": "authorized_for_release_name_title", "type": "text", "label": "Authorized for Release — Name & Title"}, {"id": "authorized_for_release_signature", "role": "verifier", "type": "signature", "label": "Signature", "width": "half"}, {"id": "release_date", "type": "date", "label": "Release Date", "width": "half"}, {"id": "controlled_label_id", "type": "text", "label": "Controlled Label ID", "width": "third"}, {"id": "controlled_file_supersedes_version", "type": "text", "label": "Supersedes Version", "width": "third"}, {"id": "effective_date", "type": "date", "label": "Effective Date", "width": "third"}, {"id": "file_location", "type": "text", "label": "File Location"}]}], "settings": {}, "schemaVersion": 1}, "revision_history": "v2 - 2026-10-10 - The label's bar code number is recorded.\n\nSection 1 gains an optional Bar code number field. The bar code identifies the pack that is sold, so it belongs with the label: a change of bar code is a label change, reviewed and approved here. The first-pack check on the Production Lot Record (FRM-520) compares the bar code on the pack with the number on the product's newest label review (owner's decision, 2026-10-10). Nothing else on the form changes.\n\nv2 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'v2'
 where id = '0a1b9e92-8857-49b4-ac8f-20ec9fa9f105' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "Applies to all new products, formulations, and packaging developed by Adventure Bakery—both customer-requested and internal brand items. Includes any change that may impact product safety, functionality, or labeling compliance.", "purpose": "Establishes a controlled procedure for developing new products, packaging, and specifications from concept to commercialization, ensuring compliance with regulatory, labeling, and food safety requirements.", "records": "Records are kept for every product made at the site, new or existing. For each product:\n• Product design: FRM-101 Product Request & Concept Form.\n• Formulation: FRM-501 Formula Sheet & Batch Data.\n• Label compliance: FRM-601 Label Review & Approval Form.\n• Process flow: the Process Parameters table on FRM-501, and the process flow diagram in the product's food safety plan (FSQM-016 for the rum cake).\n• Shelf-life trials: FRM-704 Finished Product Specification - the shelf life and how it was set - and the shelf-life trial check on FRM-501.\n• First production run and QC results: FRM-502 First Production Run Report & QC Results.\n• Approvals: FRM-102 Customer & Internal Approval Record (email confirmation acceptable), the site and customer approval on FRM-704, and the approval for commercial production on FRM-502.\nAn existing product that lacks one of these records has it completed. All records are retained under SOP-2.2.3 Document and Record Control Program (minimum of two years).", "procedure": ["Summary", "• Receive concept or request (internal or customer).", "• Evaluate feasibility (ingredients, allergens, process compatibility, equipment capacity).", "• Develop prototype formula and test batch.", "• Review formula with QA for ingredient compliance and label accuracy.", "• Obtain customer or internal approval before scale-up.", "• Conduct production trial and evaluate results.", "• Issue the finished product specification on FRM-704 Finished Product Specification, and the batch sheet.", "> Every product made at the site has a current FRM-704 entry before it is first released. It states the product's microbiological and chemical limits, and its labelling and packaging requirements, and is approved by the SQF Practitioner for the site and by the customer. It is reviewed by its next-review date and whenever the product, its label or its packaging changes. Staff find it under FRM-704 in the SOPs Library.", "• Maintain documentation in controlled format (revision history, product code, etc.).", "• Any change to a product, a recipe or a process is assessed and approved under FSQM-007 Change Management Program, on FRM-015, before it is made. The assessment covers the manufacturing process, not only the recipe, and whether the food safety plan has to be revised and validated first.", "Label Control - All labels must be reviewed and approved by QA prior to release. Verification includes:", "• Ingredient declaration accuracy.", "• Allergen and “may contain” statements.", "• Net weight, nutrition facts, and claims (e.g., gluten-free, vegan).", "Regulatory formatting (FDA CFR 21 §101). Labels may be reviewed by a third party or client regulatory team when required. The SQF Practitioner maintains a controlled label file with the current approved version.", "Shelf-Life Determination - Shelf life is recommended based on ingredient stability, process, and packaging type.", "Formal testing is optional and may be conducted by a third-party lab or by the client.", "• Documentation must include:", "• Date of validation (or basis of recommendation).", "• Product code and formula reference.", "• Reviewer/approver (Senior Site Management or the SQF Practitioner)."], "definitions": "", "responsibility": "• Senior Site Management (product development): Project initiation, feasibility, formula development, customer communication, and specification approval.\n• SQF Practitioner: Verification of food safety, label compliance, and record control.\n• Production Supervisor: Coordinates test runs, monitors first batch results, and assists in documentation.\n• Third-Party Laboratories (as needed): Conduct shelf-life or microbiological validation when required by customers or regulatory standards.", "form_references": "FRM-101 Product Request & Concept Form\nFRM-501 Formula Sheet & Batch Data\nFRM-601 Label Review & Approval Form\nFRM-102 Customer & Internal Approval Record\nFRM-502 First Production Run Report & QC Results\nFRM-704 Finished Product Specification\nFRM-015 Change Assessment Record", "revision_history": "v2 - 2026-10-05 - The step \"Any changes follow the Management of Change Procedure\" pointed at a procedure that did not exist. It now names FSQM-007 Change Management Program and FRM-015, issued the same day under D-04. The scope no longer names a brand as an example of an internal item. Nothing else in this procedure is changed by this revision.\n\nv3 - 2026-10-17 - Records rewritten for SQF 2.3.1.6, which is now cited: they are kept for every product made at the site, new or existing, and each kind the clause names - product design, formulation, label compliance, process flow, shelf-life trials and approvals - is tied to the form that holds it. Form references carry their numbers. Nothing else in this procedure is changed by this revision.\n\nv4 - 2026-10-17 - For SQF 2.3.2.9, which is now cited: the step that issued \"the finalized specification\" now names FRM-704 Finished Product Specification and states what the clause asks of it - one current entry for every product before first release, its microbiological and chemical limits and its labelling and packaging requirements, approval by the site and by the customer, review, and where staff find it. Nothing else in this procedure is changed by this revision.\n\nv5 - 2026-10-29 - Role names and record retention aligned to FSQM-004 and SOP-2.2.3, after the readiness review of 2026-10-29. Approved GJM.", "governing_reference": ""}$jx$::jsonb,
       revision = 'v5', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = 'a0d67a3e-a2eb-4e2c-9c90-1f600574c26c' and status = 'active' and revision = 'v4';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-301_Incoming_Material_Receiving_Inspection_Log.pdf", "path": "9973bd6d-6500-4bb1-8e5c-7e1fff53b222/files/FRM-301_Incoming_Material_Receiving_Inspection_Log.pdf"}, {"name": "FRM-301_Incoming_Material_Receiving_Inspection_Log.docx", "path": "9973bd6d-6500-4bb1-8e5c-7e1fff53b222/files/FRM-301_Incoming_Material_Receiving_Inspection_Log.docx"}], "form_schema": {"sections": [{"id": "receiving_log_section", "title": "Receiving Log", "fields": [{"id": "receiving_log", "rows": {"min": 1, "mode": "dynamic"}, "type": "grid", "label": "Receiving Log", "columns": [{"id": "time_of_arrival", "type": "time", "label": "Time of Arrival", "width": 2, "defaultTo": "now"}, {"id": "po_number", "type": "text", "label": "PO Number", "width": 2}, {"id": "supplier_name", "type": "text", "label": "Supplier (bought from)", "width": 3, "scanFact": "none"}, {"id": "brand_manufacturer", "type": "text", "label": "Brand / Manufacturer", "width": 3, "scanFact": "brand"}, {"id": "material_description", "type": "text", "label": "Material Description", "width": 5}, {"id": "lot_batch_number", "type": "text", "label": "Lot/Batch Number", "width": 3}, {"id": "carrier_name_seal", "type": "text", "label": "Carrier Name & Seal #", "width": 3}, {"id": "qty_received", "type": "number", "label": "Qty Received", "width": 2}, {"id": "net_weight", "type": "text", "label": "Net Weight (per pack)", "width": 2, "scanFact": "net_weight"}, {"id": "carrier_cleanliness", "type": "pass_fail", "label": "Carrier Cleanliness (P/F)", "width": 2}, {"id": "pkg_integrity_damage", "type": "pass_fail", "label": "Pkg Integrity & Damage (P/F)", "width": 2}, {"id": "temp", "type": "number", "unit": "°F", "label": "Temp", "width": 2}, {"id": "approved_supplier_coa_log_coc", "type": "pass_fail", "label": "Approved Supplier & COA/LOG/COC (Y/N)", "width": 2, "scanFact": "none"}, {"id": "receiver_initals", "type": "text", "label": "Receiver Initials", "width": 1, "defaultTo": "currentUserInitials"}, {"id": "comments_hold_status", "type": "text", "label": "Comments / Hold Status", "width": 4}], "scanLabel": true, "scanNotesColumnId": "comments_hold_status"}]}, {"id": "standard_receiving_instructions_section", "title": "Standard Receiving Instructions", "fields": [{"id": "verify_documentation_info", "text": "Match all incoming delivery notes against the original Purchase Order (PO). Confirm the supplier is currently listed on the facility's Approved Supplier List. If a supplier is not verified on the list, notify the SQF Practitioner for review and authorization prior to acceptance. The Supplier is who the material was bought from — for example Sysco or Restaurant Depot — not the brand on the pack, which goes in Brand / Manufacturer. The brand must match the brand approved for that material; a different brand is a substitution, and its allergen declaration is checked against the specification before use (SOP-2.3.4). A supplier that is not approved is accepted only in an emergency: mark Approved Supplier N and record EMERGENCY – NON-APPROVED SUPPLIER, who authorised it and the inspection result in Comments (SOP-2.3.4).", "type": "info", "label": "Verify Documentation"}, {"id": "inspection_criteria_info", "text": "— Carrier Hygiene: Inspect the transport vehicle for hygiene; ensure it is free from off-odors, dirt, and any evidence of pest infestation.\n— Packaging Integrity: Inspect containers and pallets for damage, including leaks, punctures, or tattered bags.\n— Documentation Review: Verify that a Certificate of Analysis (COA), Letter of Guarantee (LOG), or Certificate of Conformance (COC) is present and matches the specific lot numbers delivered.\n— Temperature Control: For refrigerated ingredients (liquid eggs and butter), verify that they are received at ≤ 40°F. These materials must be moved to refrigerated storage immediately after receipt to minimize pathogen growth to levels that render subsequent bake steps ineffective.", "type": "info", "label": "Inspection Criteria"}, {"id": "non_conformance_info", "text": "Immediately SEGREGATE any material that is damaged, expired, or out of specification. Tag the lot as “HOLD – DO NOT USE” and notify the SQF Practitioner immediately for final disposition.", "type": "info", "label": "Non-Conformance"}]}, {"id": "supervisory_verification_section", "title": "Supervisory Verification", "fields": [{"id": "verified_by_name", "type": "text", "label": "Verified By (SQF Practitioner / Designee)", "width": "full"}, {"id": "verified_by_signature", "role": "verifier", "type": "signature", "label": "Signature", "width": "half"}, {"id": "verification_date", "type": "date", "label": "Date", "width": "half"}, {"id": "verification_note", "text": "Verification must be completed within 7 working days per SQF requirements. The verifier shall check for record completeness and compliance with Critical Limits (Temperature).", "type": "info", "label": "Note"}]}], "settings": {}, "schemaVersion": 1}, "revision_history": "v2 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'v2'
 where id = '9973bd6d-6500-4bb1-8e5c-7e1fff53b222' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-905_Visitor_Sign-In_Log.docx", "path": "f2ecc943-ccba-4c50-8eb0-7727611c236d/files/FRM-905_Visitor_Sign-In_Log.docx"}, {"name": "FRM-905_Visitor_Sign-In_Log.pdf", "path": "f2ecc943-ccba-4c50-8eb0-7727611c236d/files/FRM-905_Visitor_Sign-In_Log.pdf"}], "form_schema": {"sections": [{"id": "visit", "title": "Visit", "fields": [{"id": "visit_date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "visitor_name", "type": "text", "label": "Visitor name", "width": "third", "required": true, "showInList": true}, {"id": "company", "type": "text", "label": "Company / organisation", "width": "third", "showInList": true}, {"id": "purpose", "type": "select", "label": "Purpose of visit", "width": "half", "options": ["Contractor / maintenance", "Audit or inspection", "Supplier", "Customer", "Pest control", "Delivery", "Other"], "required": true, "showInList": true}, {"id": "host", "type": "text", "label": "Host (the employee the visitor is here to see, responsible for them on site)", "width": "half", "required": true}, {"id": "areas", "help": "Production floor, packaging, storage, etc. Visitors remain within approved areas only.", "type": "text", "label": "Areas entered", "width": "full"}, {"id": "time_in", "type": "time", "label": "Time in", "width": "third", "required": true}, {"id": "time_out", "type": "time", "label": "Time out", "width": "third"}]}, {"id": "health", "title": "Health declaration — every visit", "fields": [{"id": "health_info", "text": "SQF 11.3.4.3 requires that visitors showing visible signs of illness are not permitted into any area where food is handled or processed. The same rules apply to our own staff. This declaration is made at every visit.", "type": "info", "label": "Why we ask"}, {"id": "no_symptoms", "type": "pass_fail", "label": "Do you have any of the following symptoms today: vomiting, diarrhoea, jaundice, fever with sore throat, discharge from the eyes, ears or nose, or an infected wound, boil or sore?", "width": "full", "labels": {"fail": "Yes, I have at least one of these", "pass": "No, I have none of these"}, "required": true, "naAllowed": false}, {"id": "wounds_covered", "type": "pass_fail", "label": "Do you have any cut or graze on your hands or exposed skin?", "width": "full", "labels": {"na": "No cuts or grazes", "fail": "Yes, and it is not covered", "pass": "Yes, and it is covered with the dressing provided"}, "required": true}, {"id": "health_notes", "type": "textarea", "label": "Anything the host should know", "width": "full"}]}, {"id": "entry", "title": "Entry", "fields": [{"id": "entry_info", "text": "11.3.4.1 gives two routes into a food handling area: the visitor is briefed on the site's food safety and hygiene rules, or the visitor is escorted at all times by an authorized employee. The briefing is the FRM-906 acknowledgement, signed on the first visit and valid for twelve months or until FRM-906 is revised. The acknowledgement this visit relies on is recorded below. A visitor without a valid acknowledgement is NOT left unaccompanied.", "type": "info", "label": "Before entry"}, {"id": "ack_date", "type": "date", "label": "FRM-906 acknowledgement signed on", "width": "third"}, {"id": "ack_response_id", "type": "text", "label": "FRM-906 entry reference", "width": "third"}, {"id": "entry_route", "type": "select", "label": "Route under 11.3.4.1", "width": "third", "options": ["Briefed — FRM-906 completed and signed", "Escorted at all times by an authorized employee", "Both", "Entry refused"], "required": true}, {"id": "escort_name", "type": "text", "label": "Escort, where escorted", "width": "half"}, {"id": "entry_notes", "help": "Anything refused, restricted, or worth recording about this visit", "type": "textarea", "label": "Notes", "width": "full"}]}, {"id": "signoff", "title": "Sign-off", "fields": [{"id": "visitor_signature", "type": "signature", "label": "Visitor", "width": "full", "capture": "drawn", "required": true, "statement": "My health declaration above is true today. If I am admitted: I have removed jewellery and loose objects (11.3.4.2); I will wear the protective clothing issued to me — hairnet, beard cover where applicable, lab coat, footwear; I will enter and leave by the staff entrance and wash my hands on entering (11.3.4.4); and I will follow the site's food safety and hygiene rules for the whole of my visit."}, {"id": "retention_note", "text": "Completed visitor records are retained by QA for a minimum of two years (FSQM-012 Part 6).", "type": "info", "label": "Retention"}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "Visitor — {visit_date} — {visitor_name}"}}, "revision_history": "v5 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'v5'
 where id = 'f2ecc943-ccba-4c50-8eb0-7727611c236d' and status = 'active' and revision = 'v5';
update public.sop_documents set content = $jx${"scope": "It applies to all labels created, reviewed, and approved before printing or production.", "purpose": "This procedure ensures that all product labels used at Adventure Bakery comply with FDA labeling regulations (21 CFR Part 101), customer requirements, and internal quality standards. This SOP supports SQF Code 2.6.1 – Product Identification and Traceability.", "records": "• Approved label files and signed approval forms\n• Label change log and revision history\n• Supporting documentation for claims and certifications\n• Supplier or client correspondence related to label approval\nLabel review records are retained for a minimum of 2 years or the shelf life of the product, whichever is longer.", "procedure": ["1. Label Submission: Receive the label from the client, designer, or third party in the proper digital format (print-ready PDF, AI, or PNG).", "2. Confirm the label includes all required information:", "• Product Identity – clear and descriptive name.", "• Net Quantity Statement – weight or volume in oz and g/mL on the principal display panel.", "• Ingredients List – ingredients listed in descending order by weight. For composite ingredients (e.g., “vegetable oil”), verify that the components are broken down (e.g., “soybean oil, canola oil”).", "• Allergen Declaration – ensure the Top 9 allergens (milk, eggs, fish, shellfish, tree nuts, peanuts, wheat, soybeans, sesame) are clearly stated. Check for “Contains” or “May contain” statements if applicable.", "• Nutrition Facts Panel – ensure it meets FDA format and includes all required values (calories, macronutrients, vitamins, minerals).", "• Manufacturer or Distributor Information – verify the name and address are correct and formatted with “Manufactured for” or “Distributed by” if applicable.", "• Expiration or Best-By Date – confirm it is present (optional but recommended for perishable products).", "• Storage Instructions – check for clear guidance (e.g., “Refrigerate after opening,” “Store in a cool dry place”).", "• Claims and Certifications – verify claims such as organic, non-GMO, vegan, kosher, or gluten-free are supported by appropriate certification logos and statements. Reference the “Claims for Food Ingredients” file for verification.", "• Barcode / UPC – ensure it is scannable and correct.", "3. Ensure label design meets readability requirements: legible font size (minimum 1/16 inch height), contrasting colors, and consistent placement of required panels.", "4. Verify that all claims are truthful and not misleading. Certifications must be current and traceable to the supplier or certifying agency.", "5. If any section is missing, incorrect, or non-compliant, return the label to the source with written notes identifying required corrections.", "6. Once compliant, sign the Label Review Approval Form, mark the version as “Approved,” and save it in the product’s digital folder. Provide the final approved label to production and packaging.", "7. When a new version of a label is approved, the previous version is marked “Obsolete” and removed from use to prevent mix-ups."], "definitions": "", "responsibility": "The SQF Practitioner reviews each label for completeness, accuracy, and compliance. QA retains final approval and recordkeeping responsibility, has final approval authority for all labels, and maintains the master list of approved versions.", "form_references": "FRM Label Review & Approval Form\nFRM Label Change Control Log ", "revision_history": "v2 - 2026-10-29 - Role names and record retention aligned to FSQM-004 and SOP-2.2.3, after the readiness review of 2026-10-29. Approved GJM.", "governing_reference": ""}$jx$::jsonb,
       revision = 'v2', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '70a732b2-74a4-4352-bfa9-8e12c02792bc' and status = 'active' and revision = 'v1';
