update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-205_Supplier_Non-Conformance_Corrective_Action_Report.pdf", "path": "db429fce-f783-422f-8258-08b27f399fd1/files/FRM-205_Supplier_Non-Conformance_Corrective_Action_Report.pdf"}, {"name": "FRM-205_Supplier_Non-Conformance_Corrective_Action_Report.docx", "path": "db429fce-f783-422f-8258-08b27f399fd1/files/FRM-205_Supplier_Non-Conformance_Corrective_Action_Report.docx"}], "form_schema": {"sections": [{"id": "section_1", "title": "Section 1 — Non-Conformance Details", "fields": [{"id": "info_1", "text": "To be completed by the SQF Practitioner and sent to the supplier.", "type": "info", "label": "Completion Instructions"}, {"id": "scar_number_year", "type": "text", "label": "SCAR Number (Year)", "width": "half"}, {"id": "scar_number_sequential", "type": "text", "label": "SCAR Number (Sequential Number)", "width": "half"}, {"id": "date_sent", "type": "date", "label": "Date Sent", "width": "half"}, {"id": "required_response_date", "type": "date", "label": "Required Response Date", "width": "half"}, {"id": "supplier_name", "type": "text", "label": "Supplier Name", "width": "half", "required": true, "showInList": true}, {"id": "po_number", "type": "text", "label": "P.O. Number", "width": "half", "showInList": true}, {"id": "supplier_representative_name", "type": "text", "label": "Supplier Representative Name"}, {"id": "supplier_contact", "type": "text", "label": "Supplier Contact (email / phone)"}, {"id": "material_name_description", "type": "text", "label": "Material Name / Description"}, {"id": "supplier_lot_batch_number", "type": "text", "label": "Supplier Lot / Batch Number", "width": "half"}, {"id": "qty_affected", "type": "text", "label": "Qty Affected", "width": "half"}, {"id": "description_of_defect_incident", "type": "textarea", "label": "Description of Defect / Incident"}, {"id": "issued_by_qa", "type": "text", "label": "Issued By (QA)", "width": "half"}, {"id": "issued_by_date", "type": "date", "label": "Date", "width": "half"}, {"id": "issued_by_signature", "role": "filler", "type": "signature", "label": "Signature"}]}, {"id": "section_2", "title": "Section 2 — Supplier Investigation & Response", "fields": [{"id": "info_2", "text": "To be completed by the supplier and returned by the required response date.", "type": "info", "label": "Completion Instructions"}, {"id": "root_cause_analysis", "type": "textarea", "label": "Root Cause Analysis (how and why the non-conformance occurred)"}, {"id": "corrective_actions_taken", "type": "textarea", "label": "Corrective Action(s) Taken (to resolve the immediate non-conformance)"}, {"id": "preventative_actions", "type": "textarea", "label": "Preventative Action(s) (to prevent recurrence)"}, {"id": "implementation_deadline", "type": "date", "label": "Implementation Deadline"}, {"id": "completed_by_supplier_representative", "type": "text", "label": "Completed By (Supplier Representative)", "width": "half"}, {"id": "supplier_signature", "role": "filler", "type": "signature", "label": "Signature"}, {"id": "supplier_signature_date", "type": "date", "label": "Date", "width": "half"}]}, {"id": "section_3", "title": "Section 3 — Final QA Disposition & Sign-off", "fields": [{"id": "info_3", "text": "To be completed by the SQF Practitioner.", "type": "info", "label": "Completion Instructions"}, {"id": "final_disposition_decision", "type": "select", "label": "Final Disposition Decision (check one)", "options": ["APPROVED FOR RELEASE: Corrective action accepted; material/supplier confirmed compliant for continued use.", "DESTROY / DISPOSE: Material cannot be salvaged; verified disposal completed and documented.", "Other"]}, {"id": "other_disposition", "type": "text", "label": "Other Disposition", "width": "half"}, {"id": "justification_effectiveness_verification", "type": "textarea", "label": "Justification / Effectiveness Verification (internal spec verification, re-inspection, or testing findings)"}, {"id": "verification_checkbox", "type": "checkbox", "label": "Verification: Corrective-action effectiveness has been confirmed and this SCAR is closed."}, {"id": "qa_leader_name_title", "type": "text", "label": "Name & Title", "width": "half"}, {"id": "qa_leader_signature", "role": "verifier", "type": "signature", "label": "Signature"}, {"id": "qa_leader_signature_date", "type": "date", "label": "Date", "width": "half"}]}], "settings": {}, "schemaVersion": 1}, "revision_history": "New - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
