update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-906_Visitor_GMP_Acknowledgement.docx", "path": "7e50e482-0f81-4d35-9b8c-6f97eda25209/files/FRM-906_Visitor_GMP_Acknowledgement.docx"}, {"name": "FRM-906_Visitor_GMP_Acknowledgement.pdf", "path": "7e50e482-0f81-4d35-9b8c-6f97eda25209/files/FRM-906_Visitor_GMP_Acknowledgement.pdf"}], "form_schema": {"sections": [{"id": "visitor", "title": "Visitor", "fields": [{"id": "ack_date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "visitor_name", "type": "text", "label": "Visitor name", "width": "third", "required": true, "showInList": true}, {"id": "company", "type": "text", "label": "Company / organisation", "width": "third", "showInList": true}, {"id": "phone", "help": "Only used so you can find yourself at your next visit.", "type": "text", "label": "Phone number, or its last four digits (optional)", "width": "third", "maxLength": 30}]}, {"id": "rules", "title": "Food Safety and Hygiene Rules", "fields": [{"id": "rules_intro", "text": "Adventure Bakery makes food. Everything below exists to keep what we make safe for the people who eat it. Read these rules, ask your host if anything is unclear, and sign at the bottom to confirm you have understood them.\n\nThis briefing is what SQF 11.3.4.1 requires before a visitor enters a food handling area. You sign it on your first visit; it stays valid for twelve months, or until these rules are revised, and you will be asked to read and sign it again after that. If you have not been briefed, you must be escorted at all times instead.", "type": "info", "label": "Please read before entering"}, {"id": "rules_table", "rows": [["1", "Sign in on FRM-905 at every visit, before entering any food handling, processing or storage area."], ["2", "Remove jewellery and other loose objects. Plain wedding bands with no stones are the only exception. This applies to management staff equally."], ["3", "Wear the protective clothing issued at entry — hairnet covering all hair with both ears covered, beard cover where applicable, lab coat, and shoe covers or dedicated footwear."], ["4", "Wash your hands on entering a food handling or processing area, after using a toilet, after eating, drinking or smoking, and after touching anything that is not clean."], ["5", "Enter and exit through the staff entrance points only."], ["6", "Do not eat, drink, chew gum, smoke or spit anywhere product is made, stored or exposed."], ["7", "Remain within the areas your host has approved."], ["8", "Do not touch ingredients, packaging, product or equipment unless the SQF Practitioner has authorized you to."], ["9", "Do not enter if you have any symptom of illness. You make a health declaration on FRM-905 at every visit."], ["10", "Contractors: agree your work area and its segregation with the SQF Practitioner or Supervisor before starting; account for all tools, parts and materials before and after the work; and if the work introduces glass or brittle plastic, it must be recorded on FRM-907 under SOP-11.7.3."]], "type": "reference_table", "label": "The rules", "columns": ["#", "Rule"]}]}, {"id": "acknowledgement", "title": "Acknowledgement", "fields": [{"id": "ack_statement", "text": "I have read and understood the food safety and hygiene rules above. I will follow them on every visit while this acknowledgement is valid, and I will do what my host asks of me while I am on site. I understand that not following them means being asked to leave the production areas.", "type": "info", "label": "Acknowledgement"}, {"id": "visitor_signature", "type": "signature", "label": "Visitor", "width": "full", "capture": "drawn", "required": true}, {"id": "retention_note", "text": "This acknowledgement is valid for twelve months from the date above, or until FRM-906 is revised. It is retained by QA for a minimum of two years after the last visit that relied on it (FSQM-012 Part 6).", "type": "info", "label": "Retention"}]}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "Acknowledgement — {ack_date} — {visitor_name}"}}, "revision_history": "v4 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'v4'
 where id = '7e50e482-0f81-4d35-9b8c-6f97eda25209' and status = 'active' and revision = 'v4';
update public.sop_documents set content = $jx${"scope": "Every controlled document of the SQF System - policies, programs (FSQM), procedures (SOP), forms (FRM), reports (REP) and training modules (TRN) - and every record made on them.", "purpose": "How this site controls its documents and keeps its records, so that people work from the current version and every record can be found and trusted.", "records": "• The controlled documents, with their revision histories and the earlier versions the Team Portal keeps\n• The Document Register and the FSMS Index - pages of the Team Portal\n• FRM-001 - the yearly review", "procedure": ["Documents", "• The controlled documents are kept in the Team Portal, in the SOPs Library. That copy is the only controlled one. A printed or downloaded copy is uncontrolled and is checked against the Team Portal before it is used (SQF 2.2.2.1).", "• Each document carries its number, title, revision, effective date, approver and the SQF clauses it answers. A document is a draft until Senior Site Management approves it; only then is it issued and in force.", "• Every team member can read every issued document. Only people Senior Site Management has authorized can change one.", "• A change to an issued document is a new revision: the revision goes up, a new effective date is set, and the reason is written in the document's revision history. The Team Portal keeps a copy of the version that was replaced, so an earlier version can always be produced (SQF 2.2.2.1).", "• An issued document that is no longer used is archived, not deleted. It leaves the list of current documents and is kept.", "• Staff are told of a new or changed document that affects their work by a notice in the Team Portal or by the training assigned for it (SOP-2.9).", "Numbering", "• Programs, forms, reports, policies and training modules carry a type and a three-digit number - FSQM, FRM, REP, POL, TRN. For forms and reports the hundreds digit is the stage of the process: 000 the food safety system, 100 new products, 200 suppliers, 300 receiving, 400 storage, 500 production, 600 packaging, 700 quality checks and release, 800 dispatch, 900 sanitation, 950 training.", "• Procedures (SOP) are numbered by the SQF clause they carry out, so SOP-2.3.4 is the procedure for clause 2.3.4. The two schemes are deliberate.", "• A number stays with its document for life. The revision is recorded on the document and is not part of the number. The Document Register in the Team Portal lists every document by number.", "Records", "• Records are made on the forms in the Team Portal as the work is done. Each entry carries who made it and when, and is signed by the person who did the check (SQF 2.2.3.2).", "• Where a paper sheet is used on the floor, it is entered in the Team Portal within one working day, and the paper is kept with the batch records.", "• A submitted record is not changed. If one has to be corrected, an authorized person reopens it, and the Team Portal records who did.", "• An entry stays tied to the revision of the form it was made on.", "• The SQF Practitioner reviews the records at the frequencies in the verification schedule (FSQM-017, Part 6) (SQF 2.2.3.1).", "Keeping records", "• Records are kept for at least two years, never less than the shelf life of the product plus twelve months, and longer where a customer or the law requires it (SQF 2.2.3.3). This is the site's record retention policy: a document that says a record is 'retained per the record retention policy' means this rule.", "• Access to the Team Portal is by personal sign-in and is limited by role, so a record can be read by those who need it and changed only as set out above (SQF 2.2.3.3).", "• Retention samples are a separate matter and are kept as FSQM-014 sets out.", "• Each lot carries the four-digit lot code set out in FSQM-021: the last digit of the year and the three-digit day of the year on which the product was baked.", "Review", "• Once a year the SQF Practitioner reviews the documents through the FSMS Index (FSQM-010), and each program is reviewed as it states. The result is reported at the management review on FRM-001."], "attachments": [{"name": "SOP-SOP-2.2.3 Document and Record Control Program (1).pdf", "path": "92b22fba-b8e3-4062-ba82-00fa9461b8da/files/SOP-SOP-2.2.3_Document_and_Record_Control_Program_1_.pdf"}], "definitions": "Controlled document: a document of the SQF System kept in the Team Portal with a number, a revision, an effective date and an approver.\nIssued: approved and in force; shown as active in the Team Portal.\nRecord: a completed entry on a form, or another document that shows an activity was done.", "responsibility": "SQF Practitioner - writes and revises documents, keeps each document's details correct, reviews records as the verification schedule sets out, and reviews the documents each year. The substitute SQF Practitioner covers when the SQF Practitioner is away.\nSenior Site Management - approves every controlled document before it is issued, and decides who may change documents.\nAll staff - work from the current document in the Team Portal and make their records on the current form.", "form_references": "FRM-001 - Management Review Record", "revision_history": "v1 - 2025-10-28 - First issue.\n\nv2 - 2026-10-07 - REWRITTEN under D-08. The first issue named a Quality Leader, a position the site does not have; said superseded versions were exported as PDF, which the Team Portal now does by keeping a copy of every replaced revision; and said production records were kept as hard copies, when they are made on the forms in the Team Portal. The numbering rule, which the gap assessment read as inconsistent, is stated here: procedures by SQF clause, every other document by type and stage. The site chose this procedure as its document control procedure; an older unissued draft of the same subject, FSQM-008, was never issued and has been removed. The SQF reference now names the clauses: 2.2.2.1 and 2.2.3.1 to 2.2.3.3.\n\nv3 - 2026-10-29 - Role names and record retention aligned to FSQM-004 and SOP-2.2.3, after the readiness review of 2026-10-29. Approved GJM. Retention is now 'at least two years, never less than the shelf life plus twelve months', which every program already stated, and is named as the site's record retention policy.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 2.2.2.1 (document control), 2.2.3.1, 2.2.3.2 and 2.2.3.3 (records).\n\nFSQM-010 Food Safety Management System Index - where each part of the system is kept.\nFSQM-017 Validation and Verification Program - the schedule of record reviews.\nFSQM-014 Product Sampling, Inspection and Analysis Program - retention samples.\nFSQM-021 Product Identification and Traceability Program - the lot code.\nFSQM-005 Management Review Program; SOP-2.9 Training & Recordkeeping."}$jx$::jsonb,
       revision = 'v3', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '92b22fba-b8e3-4062-ba82-00fa9461b8da' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"scope": "Applies to all persons entering food handling, processing or storage areas at the Adventure Bakery facility — employees, temporary staff, contractors, maintenance personnel, auditors, visitors and management.\n\nThis program is the umbrella document for SQF Food Safety Code: Food Manufacturing, Edition 9, Module 11.3 (Personnel Hygiene) and Module 11.4 (Personnel Processing Practices). The remaining Module 11 GMPs are implemented through documents that already exist and are referenced here rather than restated:\n\nPre-operational inspection and release — SOP-11.2.12, recorded on FRM-903.\nEquipment and utensil cleaning — SOP-901 to SOP-906 (SSOPs).\nSanitation schedule and verification — FRM-901, FRM-902, FRM-903.\nGlass and brittle plastic — SOP-11.7.3, FRM-907, FRM-908.\nAllergen changeover — FSQM-027.\nSite food safety inspections — FSQM-022.\nTraining and records — SOP-2.9, FRM-952, FRM-953, REP-951.\n\nNot covered here: premises and equipment construction (11.2), water, ice and air (11.5), storage and transport (11.6), and separation of functions (11.7) other than glass control.", "purpose": "To document the Good Manufacturing Practices applied at Adventure Bakery, LLC — personnel health and hygiene, handwashing, clothing and personal effects, visitors and contractors, staff amenities, and processing practices — and to state how each is implemented, verified and trained, so that food safety is controlled and assured across the scope of certification.", "records": "Visitor sign-in and GMP acknowledgement — FRM-905 and FRM-906, retained a minimum of two years.\nDaily pre-operation and amenity check — FRM-903, retained per the record retention policy.\nPeriodic GMP and food safety inspections and their corrective actions — per FSQM-022, retained per the record retention policy.\nRisk assessments for permitted jewellery exceptions — held by the SQF Practitioner with this program, for as long as the exception stands plus one audit cycle.\nIllness, injury and bodily-fluid incident dispositions — held by QA, retained per the record retention policy.\nTraining assignment, completion and competency — Team Portal, FRM-952, FRM-953 and REP-951, retained per SOP-2.9.", "procedure": ["SCOPE AND APPLICATION OF GOOD MANUFACTURING PRACTICES (SQF 2.4.2.1, 2.4.2.2)", "• The Good Manufacturing Practices set out in Module 11 of the SQF Food Safety Code: Food Manufacturing apply in full to the scope of certification — the manufacture, baking, packing and storage of baked products at this facility.", "• **No exemption from any Module 11 requirement is claimed by this program.** Where the site determines that a requirement does not apply, or that an alternative control achieves the same outcome, that determination is recorded in **FSQM-013** (Module 11 Applicability & Exemption Analysis) as a written risk analysis stating the justification or the evidence of effectiveness, approved by the SQF Practitioner, **before** it takes effect. An undocumented exemption is a non-conformance against 2.4.2.1.", "• The GMPs in Module 11.3 and 11.4 are stated in Parts 2 to 8 below. The remaining Module 11 GMPs are implemented through the documents listed in the Scope: SOP-11.2.12 and FRM-903 (pre-operational inspection), SOP-901 to SOP-906 (equipment and utensil cleaning), FRM-901 and FRM-902 (sanitation schedule and verification), SOP-11.7.3 with FRM-907 and FRM-908 (glass and brittle plastic), FSQM-027 (allergen changeover), FSQM-022 (site food safety inspections), and SOP-2.9 (training and records).", "HEALTH, ILLNESS AND INJURY (SQF 11.3.1.1, 11.3.1.2, 11.3.1.3)", "• Personnel known to be carriers of an infectious disease that presents a health risk to others shall not engage in processing or packing food, and shall not enter storage areas where food is exposed.", "• Staff shall report to their supervisor, **before starting work**, any of: vomiting, diarrhoea, jaundice, fever with sore throat, discharge from the eyes, ears or nose, or an infected wound, boil or sore. A person reporting any of these shall not enter a food handling or processing area.", "• A person excluded under this Part returns to food handling work only when free of symptoms and cleared by their supervisor.", "• **Exposed cuts, sores or lesions** — personnel with these shall not handle exposed product, primary (food-contact) packaging, or food-contact surfaces. Minor cuts or abrasions on exposed skin shall be covered with a **coloured, metal-detectable bandage** or an equivalent waterproof, coloured dressing; where the injury is on the hand, a glove shall be worn over the dressing. A lost dressing is treated as a foreign-material incident and reported immediately.", "• Staff shall not cough, sneeze or spit over product, ingredients, packaging or food-contact surfaces, and shall wash their hands afterwards.", "• **Spillage of bodily fluid** — the area is cleared, and a trained staff member ensures every affected area is cleaned and sanitized and that all affected materials and product are quarantined or disposed of. The incident and its disposition are recorded.", "HANDWASHING (SQF 11.3.2.1 to 11.3.2.6)", "• **Hands shall be clean.** All staff, contractors and visitors shall wash their hands: (i) on entering a food handling or processing area; (ii) after each visit to a toilet; (iii) after using a handkerchief or tissue; (iv) after smoking, eating or drinking; and (v) after handling wash-down hoses, cleaning materials, dropped product or contaminated material.", "• Hands shall also be washed after handling waste, after touching the face, hair or clothing, and after handling a mobile phone.", "• **Method** — wet hands with potable water, apply liquid soap, lather and scrub all surfaces including between the fingers and under the nails for at least twenty seconds, rinse, and dry with a single-use paper towel.", "• **Gloves do not replace handwashing.** Hands are washed before gloves are put on and at every trigger listed above; gloves are changed, not washed, at those points.", "• **Handwashing stations — three are provided:** one in each of the two lavatories, and one immediately inside the personnel access point into the production area from the office, break room and reception. Each is supplied with hot and cold running potable water, a paper towel dispenser, and a bin for used paper towels.", "• **Soap is supplied from a hands-free dispenser** — more than the fixed dispenser 11.3.2.3 (ii) asks for. **Paper towels are presented so that a towel can be taken without touching the dispenser housing or anything else.** What 11.3.2.3 (iii) is protecting is clean hands on the way to being dried: hands washed and then pressed against a housing that dirty hands last touched are no longer clean. Taking the towel without contact meets that, and no member of staff need touch the dispenser to dry their hands.", "• **The basins are ceramic** — impervious, non-corrosive and easily cleaned, which is what 11.3.2.3 means by \"stainless steel or similar non-corrosive material\". Ceramic is also **brittle**, so a ceramic fixture inside a food handling area is controlled as a brittle item: listed on **FRM-907** (Glass & Brittle Plastic Register) and inspected for chips and cracks with the rest of that register under **SOP-11.7.3**. A chipped basin over a hand-washing point is a foreign-material route, not just a maintenance job.", "• **One station serves the production floor**, immediately inside its personnel access point, which is the floor's only entrance from non-production space. 11.3.2.2 asks for further stations throughout food handling and processing areas *as required*; at this floor's size and layout one is sufficient, and that judgement is revisited if the layout changes or the floor grows.", "• Handwashing stations are for handwashing only. They shall not be used to wash equipment, utensils or cloths.", "• **Signage** instructing people to wash their hands before entering food processing areas is displayed in a prominent position in the break room, at the break room exit, in both toilet rooms and at the entrance to production, **in English and Spanish** — the languages understood by site personnel, consistent with FSQM-002.", "• The site operates **no designated high-risk processing area**. Where such an area is established, hands-free taps and hand sanitizers shall be provided at its handwashing stations (11.3.2.4).", "CLOTHING, HAIR AND PROTECTIVE WEAR (SQF 11.3.3.1 to 11.3.3.7)", "• **Basis of this policy — the risk analysis required by 11.3.3.1.** The hazards the clothing and hair policy controls are: hair and beard hair falling into open product; fibres, buttons, drawstrings and other loose components detaching from garments; soil, dust and organic matter carried in from outside the facility on clothing and footwear; microbiological transfer from street clothing and from garments stored against product or packaging; and allergen carry-over on protective clothing worn across a changeover. The controls chosen against those hazards are: full hair and beard containment in every area where product is exposed; site-designated outer garments that are smooth, cleanable and free of external components that can detach; footwear controlled at the point of entry so external soil does not reach the floor; separation of street clothing from clean protective clothing and from all food and packaging; and removal or change of protective clothing at changeovers and whenever it becomes a contamination risk. This analysis is reviewed whenever the process, the product range or the facility layout changes.", "• Wear clean, designated outer garments, and arrive at the facility in clean clothing free of soilage or foul odour. Change lab coats if they become soiled.", "• Wear hairnets so both ears are covered and all hair is contained; wear a beard net covering all facial hair while in production and storage areas.", "• Clothing, including shoes, shall be clean at the start of each shift and maintained in a serviceable condition. Excessively soiled uniforms shall be changed or replaced as soon as they present a contamination risk — not at the end of the shift.", "• Wear pants that fully cover the torso and ankles; wear a belt if pants sag.", "• **Footwear is controlled by sanitizing foot baths, and every person passes through them.** There are two: one at the entrance to the production area from the office, break room and reception, and one at the walkthrough between the production area and the inventory and packaging area. External soilage — dirt, faecal matter, decomposing material or other foreign matter — shall not be carried into production or storage areas.", "• **Foot bath strength — Noble Sani-512 at 1:160**, which is 4.0 fluid ounces of product per 5 gallons of water, or 0.8 fl oz per gallon. **This is deliberately stronger than the 1:512 food-contact dilution** used on equipment and utensils in the SSOPs. A foot bath carries heavy organic soil off the floor, and that soil consumes quat: made up at the weaker food-contact ratio the solution deactivates and leaves footwear unsanitized. **The two strengths are for two different jobs — never make a foot bath at the food-contact dilution, and never sanitize a food-contact surface at the foot-bath dilution.** The foot-bath dilution is not a no-rinse food-contact strength.", "• **The two dilutions are made up into separate, clearly labelled containers**, so the foot-bath solution and the food-contact solution are never drawn from the same vessel. That labelling is the control which keeps two strengths of one product from reaching the wrong job — the solutions look identical, and only the label distinguishes them.", "• **Foot bath maintenance — the check is scheduled, the change is conditional.** Each bath is checked **at the start of every production day**: looked at, and read with a quat test strip. The solution is **changed when the strip reads below target, when the bath is visibly soiled, or when it has been diluted** by water carried in on footwear or by washdown. It is not replaced on a fixed schedule — a bath still at strength and still clean is doing its job, and dumping it regardless spends chemical without adding control. The baths are stripped and thoroughly cleaned **monthly**, and sooner if required.", "• The daily check is what makes the conditional change a control rather than a guess. The soil a bath lifts off the floor is exactly what spends the quat, so an unchecked bath is weaker than its label says however carefully it was mixed — and nobody can tell by looking at it. **The strip must be able to read this solution:** at 1:160 the bath is roughly three times the strength of the 1:512 food-contact solution, so the 0-400 ppm strips used on food-contact surfaces will saturate and read \"high\" whatever the true value. A high-range quat strip is required for the baths. The daily check is recorded on **FRM-903**; the monthly strip-down is scheduled on **FRM-901**.", "• **Disposable gloves and aprons shall be changed after each break, on every re-entry to the processing area, and whenever damaged.** They are not washed and re-used.", "• Non-disposable aprons and gloves shall be cleaned and sanitized as required. When not in use they are stored on the racks provided in the processing area, or in designated sealed containers in personnel lockers. They shall **never** be placed or stored on packaging, ingredients, product or equipment.", "• Protective clothing shall be made from material that poses no food safety threat and is easily cleaned. It shall be cleaned after use, or at a frequency that controls contamination, and stored clean and serviceable so that it cannot pick up microbiological or allergen contamination between uses.", "• **Laundering — aprons and other protective clothing are laundered by employees at home**, with laundry detergent, and hung to dry. Home laundering is permitted, and these conditions apply to it: the garment is laundered after each use, or sooner if it becomes soiled; washed separately from heavily soiled household laundry; dried and kept in a clean, dry place; carried to and from the site in a clean, covered bag; and presented clean at the start of each shift. A garment that cannot be returned to a clean, serviceable condition is replaced rather than worn.", "• Racks are provided for the temporary storage of protective clothing when staff leave the processing area, at the **personnel access doorway into production, beside the handwashing station and the foot bath** — so the garment comes off, the foot bath is crossed and the hands are washed at one point rather than three (11.3.3.7).", "• Protective clothing is removed before entering toilet rooms, the break room, or any outside area, and is not worn outside the facility.", "JEWELLERY AND PERSONAL EFFECTS (SQF 11.3.3.8)", "• Do not wear jewellery, cosmetic items, or other objects that might fall into food, equipment or containers — including visible or exposed piercings, watches, earrings, necklaces, bracelets, fingernail polish or hardener, false fingernails and false eyelashes. **Only plain wedding bands with no stones are allowed.**", "• **Medical alert items** may be permitted on a case-by-case basis with the permission of Quality and Production supervision. **Items accepted for religious or cultural reasons** follow the same route.", "• Every permitted exception shall be covered so it cannot be lost into product, shall meet regulatory and customer requirements, and shall be supported by a **written risk assessment** recorded and retained by the SQF Practitioner with this program. Permitted exceptions are checked at GMP inspection, which is the ongoing risk management 11.3.3.8 requires — a one-time approval is not sufficient.", "• Store clothes, mobile phones, personal belongings and other non-food items in lockers or offices only. Personal items are not taken into food handling, processing or storage areas.", "VISITORS AND CONTRACTORS (SQF 11.3.4.1 to 11.3.4.4)", "• Every visitor — including contractors, maintenance personnel, auditors, suppliers, customers, guests and **management staff** — shall comply with this Part.", "• **Sign in on FRM-905** (Visitor Sign-In Log) before entering any food handling, processing or storage area.", "• **Read and acknowledge the site's food safety and hygiene rules on FRM-906** (Visitor GMP Acknowledgement) on the first visit. The acknowledgement is **renewed every twelve months and whenever FRM-906 is revised**, and a health declaration is made on **FRM-905 at every visit**. A visitor holding a valid FRM-906 acknowledgement satisfies the training requirement of 11.3.4.1; **any visitor who does not shall be escorted at all times** by an authorized employee.", "• **Remove jewellery and loose objects** in accordance with Part 5. This applies to management staff equally.", "• Wear suitable clothing and footwear and the protective wear issued at entry — hairnet, beard cover where applicable, lab coat, and shoe covers or dedicated footwear.", "• **Enter and exit through the proper staff entrance points only**, and comply with the handwashing requirements of Part 3 and the processing practices of Part 8.", "• Remain within approved areas, and not touch ingredients, packaging, product or equipment unless authorized by the SQF Practitioner.", "• **Visitors showing visible signs of illness shall not be permitted to enter** any area where food is handled or processed. The rules of Part 2 apply to visitors as they do to staff.", "• **Contractors** additionally: agree the work area and its segregation with the SQF Practitioner or Supervisor before starting; account for all tools, parts and materials before and after the work; and where the work introduces glass or brittle plastic, comply with SOP-11.7.3 and record it on FRM-907.", "• Completed visitor records are retained by QA for a minimum of **two years**. An FRM-906 acknowledgement is retained for two years after the last visit that relied on it.", "STAFF AMENITIES AND WELFARE (SQF 11.3.5.1 to 11.3.5.10)", "• Staff amenities — toilet rooms, the break room and changing areas — have documented cleaning procedures, are scheduled on **FRM-901** (Master Sanitation Schedule), and their sanitary condition is confirmed on **FRM-903** at pre-operation. They are lit and ventilated appropriately and are available to every person engaged in handling and processing product.", "• **Changing** — staff and visitors change into and out of protective clothing in the toilet rooms, which are of sufficient size for the purpose and are kept clean (11.3.5.2).", "• **Street clothing and personal items** are stored in the lockers provided in the break room, which is separate from all food-contact zones and from food and packaging storage (11.3.5.4).", "• The site processes no high-risk foods and operates no designated high-risk area, so a high-risk change area (11.3.5.3) is not provided. Showers (11.3.5.5) are not required by the processes performed here. Should either condition change, the provision shall be made before that processing begins.", "• **Toilet rooms** are accessible to staff, separate from processing and food handling operations, sufficient in number for the maximum number of staff on site, constructed so they can be easily cleaned and maintained, and kept clean and tidy. **The employee lavatory is reached through a vented airlock** rather than opening onto the processing area (11.3.5.6 ii). Provision is made for storing protective clothing and outer garments while the facilities are in use. **Cleaning tools and equipment used in toilet rooms shall never be used to clean processing areas** and are stored separately and identified for that use only.", "• **Handwashing basins** are provided immediately inside or outside the toilet room, to the specification in Part 3.", "• **Sanitary drainage** is not connected to any other drain within the premises and discharges to the sewerage system in accordance with regulations.", "• The **break room** is separate from all food contact and handling zones, is lit, and is ventilated by the site's heating and cooling system. It has **a refrigerator**, **a microwave for heating food**, and **a table with seating for all employees at one sitting** (11.3.5.9 i, ii, iv). It holds the personal-item lockers and is kept clean and free from waste materials and pests.", "• The break room has **no utensil sink** (11.3.5.9 iii), and nothing is washed up in it: **the utensils provided are disposable**, and any re-usable personal item a member of staff brings is taken home to be washed rather than washed on site. The handwash basin in the adjacent lavatory is therefore not standing in for a utensil sink — there are no utensils to wash. Used personal items are kept in the owner's locker or bag until they leave, not left out in the room. This is an alternative arrangement rather than the fixture the clause names, so it is recorded in the Module 11 exemption analysis with this justification, as 2.4.2.1 requires.", "• **Staff food is not stored in the production walk-in refrigerator.** Personal food held among ingredients is a contamination and allergen route, which is why the break room carries its own refrigeration rather than borrowing the walk-in.", "• Where an outside eating area is provided it is kept clean and free from waste materials and maintained so it does not attract pests or introduce contamination to the site.", "PROCESSING PRACTICES (SQF 11.4.1.1 to 11.4.1.4)", "• **Entry to processing areas is through the personnel access doors only.**", "• **All doors are kept closed.** Doors are not left open for extended periods during waste removal or when receiving product, ingredients or packaging.", "• Packaging, product and ingredients are kept in appropriate containers as required and **off the floor**.", "• **Waste** is contained in the bins identified for the purpose and removed from the processing area regularly; it is not left to accumulate.", "• **Wash-down and compressed air hoses** are stored on the hose racks after use and are not left on the floor.", "• Staff shall **not eat or taste any product being processed** in a food handling or contact zone, except under the sensory evaluation controls below.", "• **False fingernails, false eyelashes, eyelash extensions, long nails and fingernail polish are not permitted** when handling exposed food.", "• **Hair restraints and beard covers** are worn wherever product is exposed.", "• **Smoking, chewing, eating and spitting are not permitted** in any area where product is produced, stored or otherwise exposed.", "• **Drinking water** is permitted only under conditions that prevent contamination. Containers shall be clear and covered, and kept in designated areas away from raw materials, packaging, tools and equipment storage.", "• **Personnel flow** is managed so the potential for contamination is minimized: staff move from cleaner to less clean areas rather than back, do not move between an allergen-handling task and exposed non-allergen product without changing protective clothing and washing hands, and do not take traffic through an exposed-product area as a shortcut between other parts of the facility.", "• **Sensory evaluation — product tasting is carried out in the office adjacent to the production area**, which is outside the food handling and contact zones. No tasting of in-process product takes place on the floor (11.4.1.2 i). Product is carried to the office on clean utensils by authorized personnel, and nothing tasted is returned to the process.", "• Should it ever become necessary to evaluate within a food handling or contact zone, the site shall ensure that food safety is not compromised; that the evaluation is conducted by authorized personnel only; that a high standard of personal hygiene is practised by those conducting it; that it is carried out in an area equipped for the purpose; and that equipment used for it is sanitized, maintained and stored separately from processing equipment (11.4.1.4).", "VERIFICATION (SQF 2.5.4.3)", "• **Daily** — the pre-operation inspection under **SOP-11.2.12**, recorded on **FRM-903**, confirms that food-contact surfaces, utensils, production areas and staff amenities are sanitary and that GMP requirements are met before production begins.", "• **Periodic** — planned inspections of the site and equipment verify that this program and facility and equipment maintenance comply with the SQF Food Safety Code: Food Manufacturing. Scope, frequency and responsibility are set in **FSQM-022** (Food Safety Monitoring Program).", "• Findings are recorded. The site shall take corrections or corrective and preventive action, and shall **maintain records of inspections and of any corrective action taken**.", "• Non-compliance with this program by a member of staff or a visitor results in immediate removal from production areas. Repeat violations are documented and handled as a corrective action.", "TRAINING (SQF 2.9.2.1 iii and iv, 2.4.2.2)", "• Every employee who handles food or food-contact surfaces completes **TRN-002 Personal Hygiene & GMPs**, **TRN-002A Personnel Hygiene & Visitor Policy** and **TRN-002B Good Manufacturing Practices**. All three are active, assigned to all staff, and complete for every current member of the team. **TRN-002 exists in English and Spanish; TRN-002A and TRN-002B exist in English only.**", "• **Language (2.9.2.2).** Training on tasks critical to food safety shall be provided in languages understood by staff. One member of production staff is trained in Spanish. She completed all three modules in **English** — including TRN-002, whose Spanish version exists — because her assignments were already complete before the language-aware assignment rules applied, and completed records are deliberately never re-languaged. **This program therefore does not yet meet 2.9.2.2 for Spanish-speaking staff**, and says so rather than letting a completion record imply otherwise. The remedy is recorded in the open actions.", "• Training is delivered at induction, **before the employee works unsupervised in a food handling area**, and refreshed at the frequency set in **SOP-2.9**.", "• Competency is verified on **FRM-952**; attendance on **FRM-953**. Assignment, completion and outstanding training are held in the Team Portal and reported on **REP-951** (Training Matrix).", "• Visitors are briefed through **FRM-906**, which is the visitor training required by 11.3.4.1."], "definitions": "Food handling / contact zone — any area where product, ingredients, primary packaging or food-contact surfaces are exposed. Includes the production floor, the depositing and packing areas, and open ingredient storage.\n\nProtective clothing — outer garments, hairnets, beard covers, aprons, gloves and dedicated footwear or shoe covers worn to protect product, as distinct from personal clothing.\n\nVisitor — any person entering a food handling, processing or storage area who is not an employee of the site, including contractors, maintenance personnel, auditors, suppliers, customers and guests.\n\nEscorted — accompanied at all times by an authorized employee who is responsible for the visitor's compliance with this program.", "responsibility": "SQF Practitioner / QA — owns this program, enforces it, approves exceptions, holds the risk assessments for permitted jewellery, and verifies compliance through GMP inspection.\nSupervisors — ensure staff on their shift comply, act on non-compliance immediately, and receive illness and injury reports.\nAll staff — comply with this program, and report illness, injury and any breach they observe.\nReception / designated staff — ensure every visitor completes FRM-905 and FRM-906 before entry and is escorted or trained.\nMaintenance — maintain handwashing stations, amenities and the facility provisions this program depends on, and correct deficiencies raised by GMP inspection.", "form_references": "FRM-905 — Visitor Sign-In Log\nFRM-906 — Visitor GMP Acknowledgement\nFRM-903 — Daily Sanitation, Pre-Operation & Release Record\nFRM-901 — Master Sanitation Schedule (amenity cleaning is scheduled here)\nFRM-907 / FRM-908 — Glass & Brittle Plastic Register / Glass Breakage Incident Report\nFRM-952 / FRM-953 — Training Competency Verification Record / Training Sign-In Sheet\nREP-951 — Training Matrix\nSOP-11.2.12 — GMP / Pre-Operation Inspection\nSOP-11.7.3 — Glass & Brittle Plastic Control\nFSQM-027 — Allergen Management Program\nSOP-2.9 — Training & Recordkeeping\nFSQM-013 — Module 11 Applicability & Exemption Analysis (what this program does not claim)\nFSQM-022 — Food Safety Monitoring Program", "revision_history": "New — 2026-09-01 — Initial issue. Written to close SQF 2.4.2.2, which requires the site's applicable Good Manufacturing Practices to be documented. Covers Module 11.3 and 11.4 in full — thirty-five clauses, of which SOP-11.3 addressed about nine.\n\nSUPERSEDES SOP-11.3 Personnel Hygiene & Visitor Policy. Its dress code, jewellery list, visitor requirements, twelve-month retention and corrective-action clause are carried forward here, extended rather than rewritten. SOP-11.3 remains the active controlled document until this program is approved and issued; it is archived in the same transaction that activates this one, so the site is never without an active personnel hygiene document.\n\nSITE ARRANGEMENTS CONFIRMED 2026-09-01 by Richard Mercer. The facility facts in this program are the site's own answers, not assumptions: three handwashing stations (one in each lavatory, one immediately inside the production access point, which is the floor's only entrance from non-production space) with hot and cold potable water, waste bins, soap from a hands-free dispenser and towels that can be taken without touching the housing; handwash signage in the break room, at its exit, in both toilet rooms and at the production entrance, in English and Spanish; no designated high-risk area; protective clothing laundered by employees at home with detergent and hung to dry; footwear controlled by two sanitizing foot baths, at the production entrance and at the walkthrough to the inventory and packaging area, dosed with Sani-512 at 1:160, made up in separate clearly labelled containers from the 1:512 food-contact solution, and thoroughly cleaned monthly, with the solution changed on condition rather than on a fixed interval; ceramic handwash basins, and the protective clothing rack installed at the production entrance; changing done in the toilet rooms, personal items in break room lockers; the employee lavatory reached through a vented airlock; sanitary drainage separate and compliant; the break room separate from food zones, lit, ventilated, with a refrigerator, a microwave and a table seating all employees at one sitting, and with disposable utensils so nothing is washed up there; no fixed illness exclusion interval — supervisor clearance is the control; product tasting carried out in the office adjacent to production, never on the floor.\n\nOPEN ACTIONS AT ISSUE — two items. The forms now carry every check this program states: the daily foot bath check is a grid in section 3 of FRM-903, the monthly strip-down is on the FRM-901 schedule and in its task picker, and the ceramic basin at the production entrance is on the FRM-907 register (FRM-901 rev B, FRM-903 rev v6, FRM-907 rev v2, all effective 2026-09-01). What is left is one confirmation and one purchase.\n1. CONFIRM — the 1:160 figure against the product label. The 1:512 food-contact dilution was checked against the Sani-512 label on 2026-08-25; this foot-bath ratio has not been. A sanitizer used at a dilution its label does not carry is a label-use problem before it is an SQF problem, so confirm 1:160 appears on the label for this use — and while doing it, add the label and SDS to the Chemical Safety Data Sheets collection, which still holds only a generated summary.\n2. ACTION — high-range quat test strips for the foot baths. At 1:160 the bath runs at roughly three times the food-contact strength, which is off the top of the 0-400 ppm strips used on equipment: those will simply read high and tell the checker nothing. FRM-903's foot bath grid now carries that warning on its own label, so the person holding the strip sees it — but the strip still has to exist. Keep it with the baths, separate from the food-contact strips, for the same reason the two dilutions are made up in separately labelled containers.\n\nCARRIED INTO FSQM-013 (Module 11 Applicability & Exemption Analysis), issued 2026-09-01 under task 13.6. Two arrangements meet what a clause protects without being the fixture it names, and both now carry their written justification there: the absent break room utensil sink (11.3.5.9 iii), where nothing is washed up because utensils are disposable and personal items go home; and the paper towel dispenser (11.3.2.3 iii), which has no no-touch mechanism though a towel is taken without contacting the housing. FSQM-013 also records the high-risk clauses this program states are not engaged, and lists six Module 11 questions still needing a site answer.\n\nISSUED 2026-09-01, approved GJM. SOP-11.3 Personnel Hygiene & Visitor Policy is archived in the same transaction and is superseded by this program in full. Its dress code, jewellery list, visitor requirements, twelve-month retention and corrective-action clause are carried forward here; nothing it stated has been dropped.\n\n\nTRAINING VERIFIED 2026-09-01 under D-13 task 13.8. The training limb of 2.4.2.2, and 2.9.2.1 (iii) personal hygiene and (iv) Good Manufacturing Practices, are met by three active modules — TRN-002, TRN-002A and TRN-002B — assigned to all three members of the team, with all nine assignments complete. Records are held in the Team Portal and reported on REP-951; competency is verified on FRM-952 and attendance on FRM-953.\n\nPART 10 IS CORRECTED IN THE SAME BREATH, because as issued it was wrong. It said the modules are “available in English and Spanish and assigned in the language the employee is trained in”. Neither half held: TRN-002A and TRN-002B exist in English only, and the one Spanish-preferring member of staff completed all three in English. A claim that an auditor could disprove by asking one employee what language they trained in is worse than no claim, so Part 10 now states what is actually true and names the gap.\n\nOPEN ACTIONS AT ISSUE — a third item joins the two already listed.\n3. SPANISH TRAINING FOR 2.9.2.2. Two things are needed and they are different sizes. (a) TRN-002 already has an active Spanish deck, so a Spanish-preferring employee can be assigned it directly — this is an assignment decision, not a build, and it affects a real person's training record, so it is left to the SQF Practitioner rather than done by migration. (b) TRN-002A and TRN-002B have no Spanish version and no generator source in the repository, so producing one means either translating the original decks or authoring the content afresh from the existing English narrations. That is a build, not an afternoon. Until both are done, the position stated in Part 10 stands.\n\n\n\nv3, 2026-10-01 — VISITOR ACKNOWLEDGEMENT SIGNED ONCE, NOT AT EVERY VISIT. Part 6 required every visitor to read and acknowledge the rules on FRM-906 before entry, which in practice meant at every entry. 11.3.4.1 requires that a visitor is trained before entering or is escorted; a briefing given and signed for remains given. The acknowledgement is now completed on the first visit and renewed every twelve months and whenever FRM-906 is revised. The health declaration, which concerns the day of the visit, is made on FRM-905 at every visit, and each FRM-905 entry records the acknowledgement it relied on. Retention is extended so that an acknowledgement is kept for twelve months after the last visit that relied on it. The visitor's signature on both forms is now the visitor's own, drawn on the device, with the host recorded as witness.\n\nv4 - 2026-10-29 - SOP-204 Allergen Cleaning Procedure was archived when FSQM-027 Allergen Management Program was issued (2026-10-29); the three references to it now name FSQM-027. Nothing else changes. Approved GJM.\n\nv5 - 2026-10-29 - Role names and record retention aligned to FSQM-004 and SOP-2.2.3, after the readiness review of 2026-10-29. Approved GJM.", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 — Module 11.3 (Personnel Hygiene, 11.3.1.1 to 11.3.5.10) and Module 11.4 (Personnel Processing Practices, 11.4.1.1 to 11.4.1.4).\nSQF Food Safety Code: Food Manufacturing, Edition 9 — System Elements 2.4.2.1 (GMPs applied or exempted by written risk analysis), 2.4.2.2 (GMPs documented and implemented), 2.5.4.3 (planned site and equipment inspections with corrective action and records), and 2.9.2.1 iii and iv (personal hygiene and Good Manufacturing Practices training).\nFDA 21 CFR Part 117 Subpart B — Current Good Manufacturing Practice, in particular §117.10 (Personnel) and §117.20 (Plant and grounds)."}$jx$::jsonb,
       revision = 'v5', approved_by = 'GJM', effective_date = date '2026-10-29'
 where id = '79e050a4-e186-405f-a0d1-1c356d4a3dc6' and status = 'active' and revision = 'v4';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-002_Customer_Complaint_Report.docx", "path": "cab6ee67-e61c-4902-8bef-d4aab13864c9/files/FRM-002_Customer_Complaint_Report.docx"}, {"name": "FRM-002_Customer_Complaint_Report.pdf", "path": "cab6ee67-e61c-4902-8bef-d4aab13864c9/files/FRM-002_Customer_Complaint_Report.pdf"}], "form_schema": {"sections": [{"id": "complaint_receipt", "title": "Section 1 — Complaint Receipt", "fields": [{"id": "complaint_ref_no", "type": "text", "label": "Complaint Ref No.", "width": "half", "required": true, "showInList": true}, {"id": "date_received", "type": "date", "label": "Date Received", "width": "half", "required": true}, {"id": "received_by_csr", "type": "text", "label": "Received By", "width": "half", "required": true}, {"id": "channel", "type": "select", "label": "Channel", "width": "half", "options": ["Phone", "Email", "Written correspondence"], "multiple": true, "required": true}, {"id": "date_acknowledged_to_customer_within_24_h", "type": "date", "label": "Date Acknowledged to Customer (within 24 h)"}]}, {"id": "customer_product", "title": "Section 2 — Customer & Product", "fields": [{"id": "customer_name", "type": "text", "label": "Customer Name", "showInList": true, "suggestFrom": {"form": "FRM-011", "grid": "contacts", "field": "_label", "where": {"column": "group", "equals": "Customer (brand owner)"}, "drafts": true, "current": true}}, {"id": "contact_phone_email", "type": "text", "label": "Contact (phone / email)"}, {"id": "product_name", "type": "text", "label": "Product Name", "width": "half", "showInList": true}, {"id": "lot_batch_code", "type": "text", "label": "Lot / Batch Code", "width": "half"}, {"id": "date_best_by_code", "type": "text", "label": "Date / Best-By Code", "width": "third"}, {"id": "qty_affected", "type": "text", "label": "Qty Affected", "width": "third"}, {"id": "purchase_date", "type": "date", "label": "Purchase Date", "width": "third"}]}, {"id": "complaint_description", "title": "Section 3 — Complaint Description", "fields": [{"id": "customer_description_info", "text": "Record the customer's description in their own terms (SQF 2.1.3.1).", "type": "info", "label": "Customer description instructions"}, {"id": "complaint_description_text", "type": "textarea", "label": "Complaint Description"}]}, {"id": "classification_samples", "title": "Section 4 — Classification & Samples", "fields": [{"id": "classification", "type": "select", "label": "Classification", "options": ["Critical (food safety risk)", "Non-Critical (quality concern)"], "required": true}, {"id": "critical_non_critical_info", "text": "Critical = contamination, foreign material, allergen presence. Non-Critical = texture, flavor, packaging.", "type": "info", "label": "Classification explanation"}, {"id": "sample_available", "type": "checkbox", "label": "Sample available?", "width": "half"}, {"id": "sample_collected", "type": "checkbox", "label": "Sample collected?", "width": "half"}]}, {"id": "investigation_root_cause", "title": "Section 5 — Investigation & Root Cause", "fields": [{"id": "records_reviewed", "type": "select", "label": "Records reviewed", "options": ["Production", "Packaging", "Shipping", "Retain samples"], "multiple": true}, {"id": "investigation_findings", "type": "textarea", "label": "Investigation findings"}, {"id": "root_cause_sqf_2_5_3_1", "type": "textarea", "label": "Root cause (SQF 2.5.3.1)"}]}, {"id": "corrective_preventive_action_capa", "title": "Section 6 — Corrective & Preventive Action (CAPA)", "fields": [{"id": "capa_instructions", "text": "Critical complaints require immediate notification to management and a recall assessment (SQF 2.1.3.3).", "type": "info", "label": "CAPA instructions"}, {"id": "capa_ref", "help": "The FRM-007 number, where this complaint opened a corrective action. FSQM-009 Part 3: a critical complaint, or one alleging illness, injury, foreign material or an undeclared allergen, always opens one.", "type": "text", "label": "CAPA No.", "width": "half", "showInList": true}, {"id": "management_notified_critical", "help": "It is a requirement to notify management for any complaint classified as Critical.", "type": "select", "label": "Management notified (critical)?", "width": "half", "options": ["Yes", "N/A"]}, {"id": "recall_assessment_required", "type": "checkbox", "label": "Recall assessment required?", "width": "half"}, {"id": "corrective_and_preventive_action_taken", "type": "textarea", "label": "Corrective and preventive action taken"}, {"id": "responsible", "type": "text", "label": "Responsible", "width": "third"}, {"id": "target_date", "type": "date", "label": "Target Date", "width": "third"}, {"id": "completed", "type": "date", "label": "Completed", "width": "third"}]}, {"id": "communication_closure", "title": "Section 7 — Communication & Closure", "fields": [{"id": "communication_instructions", "text": "Final findings must be communicated to the customer within 10 business days or sooner (SOP-2.1.3).", "type": "info", "label": "Communication instructions"}, {"id": "communicated_to_customer_on_date", "type": "date", "label": "Communicated to customer on", "width": "third"}, {"id": "communicated_by", "type": "text", "label": "by", "width": "third"}, {"id": "communicated_via", "type": "text", "label": "via", "width": "third"}, {"id": "within_10_business_days", "type": "checkbox", "label": "Within 10 business days?", "width": "half"}, {"id": "customer_satisfied", "type": "checkbox", "label": "Customer satisfied?", "width": "half"}, {"id": "closed_by_quality_manager", "type": "text", "label": "Closed by (SQF Practitioner)", "width": "half"}, {"id": "closure_date", "type": "date", "label": "Date", "width": "half"}, {"id": "signature", "role": "verifier", "type": "signature", "label": "Signature"}]}], "settings": {}, "schemaVersion": 1}, "revision_history": "v2 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'v2'
 where id = 'cab6ee67-e61c-4902-8bef-d4aab13864c9' and status = 'active' and revision = 'v2';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-101_Product_Request_Concept_Form.pdf", "path": "e3fc8589-94cf-4f00-9c90-09349426a99f/files/FRM-101_Product_Request_Concept_Form.pdf"}, {"name": "FRM-101_Product_Request_Concept_Form.docx", "path": "e3fc8589-94cf-4f00-9c90-09349426a99f/files/FRM-101_Product_Request_Concept_Form.docx"}], "form_schema": {"sections": [{"id": "section_1", "title": "Project Identification", "fields": [{"id": "project_concept_name", "type": "text", "label": "Project / Concept Name", "width": "full", "required": true, "showInList": true}, {"id": "request_no", "type": "text", "label": "Request No.", "width": "half", "required": true, "showInList": true}, {"id": "date_initiated", "type": "date", "label": "Date Initiated", "width": "half"}, {"id": "origin_of_request", "type": "select", "label": "Origin of Request", "width": "full", "options": ["Internal (R&D / Sales / Management initiative)", "Customer-Requested (complete customer details below)"]}, {"id": "customer_account_name", "type": "text", "label": "Customer / Account Name", "width": "full", "required": true}, {"id": "customer_contact_phone", "type": "text", "label": "Customer Contact Phone", "width": "half", "required": true}, {"id": "customer_contact_email", "type": "text", "label": "Customer Contact Email", "width": "half", "required": true}, {"id": "requested_by", "type": "text", "label": "Requested By", "width": "half"}, {"id": "target_launch_need_by_date", "type": "date", "label": "Target Launch / Need-By Date", "width": "half"}]}, {"id": "section_2", "title": "Concept Scope & Customer Requirements", "fields": [{"id": "info_concept_scope", "text": "Define the project scope and capture all customer / consumer requirements (SQF 2.4.1.1).", "type": "info", "label": "Concept Scope Info"}, {"id": "product_concept_project_scope", "rows": 3, "type": "textarea", "label": "Product Concept & Project Scope (description, intended use, market, target attributes)", "width": "full"}, {"id": "customer_consumer_requirements", "rows": 3, "type": "textarea", "label": "Customer / Consumer Requirements (specifications, claims, packaging, delivery, regulatory, certifications)", "width": "full"}]}, {"id": "section_3", "title": "Initial Feasibility Evaluation", "fields": [{"id": "info_feasibility_evaluation", "text": "Evaluated at initiation to confirm concept, process compatibility, and allergen/ingredient feasibility (SQF 2.3.1.1).", "type": "info", "label": "Feasibility Evaluation Info"}, {"id": "feasibility_evaluation_grid", "rows": {"mode": "fixed", "labels": ["Process Compatibility / Capability\nExisting equipment & process controls can meet the target specification limits (process capability – SQF 2.3.1.1).", "Ingredient Feasibility\nRequired ingredients are available from approved suppliers and are technically suitable.", "Allergen Feasibility\nAllergen profile is compatible with the facility allergen-control program; no uncontrollable cross-contact.", "Packaging & Labeling\nPackaging format and labeling requirements are achievable and compliant.", "Regulatory / Food Safety\nConcept meets applicable FDA / regulatory and food-safety requirements."]}, "type": "grid", "label": "Feasibility Evaluation", "columns": [{"id": "yn_na", "type": "select", "label": "Y / N / NA", "options": ["Y", "N", "NA"]}, {"id": "notes", "type": "text", "label": "Notes"}]}]}, {"id": "section_4", "title": "Initial Disposition & Authorization", "fields": [{"id": "decision", "type": "select", "label": "Decision", "width": "full", "options": ["APPROVED to proceed to formulation / benchtop development.", "ON HOLD pending additional information (note below).", "REJECTED (rationale below)."], "showInList": true}, {"id": "comments_rationale", "type": "textarea", "label": "Comments / Rationale", "width": "full"}, {"id": "requested_submitted_by", "role": "filler", "type": "signature", "label": "Requested / Submitted By", "width": "half"}, {"id": "decision_date", "type": "date", "label": "Date", "width": "half"}, {"id": "reviewed_authorized_by_quality_leader", "type": "text", "label": "Reviewed & Authorized By (SQF Practitioner)", "width": "full"}, {"id": "reviewer_signature", "role": "verifier", "type": "signature", "label": "Signature", "width": "half"}, {"id": "reviewer_signature_date", "type": "date", "label": "Date", "width": "half"}]}], "settings": {}, "schemaVersion": 1}, "revision_history": "New - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'New'
 where id = 'e3fc8589-94cf-4f00-9c90-09349426a99f' and status = 'active' and revision = 'New';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-903-Daily_Sanitation.docx", "path": "96b9eed2-3665-4857-a81c-b839d4f83f9d/files/FRM-903-Daily_Sanitation.docx"}, {"name": "FRM-903-Daily_Sanitation.pdf", "path": "96b9eed2-3665-4857-a81c-b839d4f83f9d/files/FRM-903-Daily_Sanitation.pdf"}], "form_schema": {"sections": [{"id": "details", "title": "Day / Shift", "fields": [{"id": "inspection_date", "type": "date", "label": "Date", "width": "third", "required": true, "showInList": true, "defaultToday": true}, {"id": "area_line", "type": "select", "label": "Production area / line", "width": "third", "options": ["Production floor", "Dry storage room", "Other"], "showInList": true, "defaultValue": "Production floor"}, {"id": "shift", "type": "select", "label": "Shift", "width": "third", "options": ["1st Shift", "2nd Shift", "3rd Shift"], "showInList": true, "defaultValue": "1st Shift"}, {"id": "product_run", "help": "What is being produced today (leave blank if no production)", "type": "text", "label": "Product / batch run", "width": "half", "lotLink": {"fromField": "inspection_date"}, "suggestFrom": {"form": "FRM-501", "field": "product_name", "drafts": true}}]}, {"id": "preop_surfaces", "title": "1. Pre-Operation Cleanliness Check", "fields": [{"id": "surface_check", "rows": {"mode": "fixed", "labels": ["Tables", "Mixers", "Bowls", "Utensils", "Pans", "Racks", "Ovens", "Scales", "Depositors", "Floors", "Handwash stations (clean, stocked, draining)", "Restrooms / sanitary facilities", "Break room / lockers (staff amenities)"], "addLabel": "Add item", "deletable": true, "labelHeader": "Item / Surface"}, "type": "grid", "label": "Surface & equipment check", "columns": [{"id": "visibly_clean", "type": "pass_fail", "label": "Visibly clean", "width": 1, "required": true}, {"id": "sanitized", "type": "pass_fail", "label": "Sanitized", "width": 1, "required": true}, {"id": "corrective", "type": "text", "label": "Corrective action / comments", "width": 3}]}], "description": "Before production starts, following cleaning and sanitation, confirm each item is visibly clean and sanitized (SQF 11.2.5.7). The clause covers the processing areas and product contact surfaces AND the staff amenities and sanitary facilities, so all of them are listed here. Mark Pass, Fail, or N/A — N/A is the right answer for \"Sanitized\" on an area that is cleaned but not sanitized, such as a locker room. Note any corrective action taken before start-up. Add or remove items as the line changes."}, {"id": "equipment_ssop", "title": "2. Production Equipment — Cleaned & Sanitized per SSOP", "fields": [{"id": "equipment_status", "rows": {"mode": "fixed", "labels": ["Hobart V-1401 Mixer — SOP-901 / FRM-909", "Kook-E-King Depositor — SOP-902 / FRM-910", "Beldos 275 Depositor — SOP-903 / FRM-911", "Smipack S560NA Shrink Wrapper — SOP-601", "Groen TDB Kettle — SOP-904 / FRM-912", "Molds — SOP-906 (recorded here)"], "addLabel": "Add equipment", "deletable": true, "labelHeader": "Equipment"}, "type": "grid", "label": "Equipment", "columns": [{"id": "status", "type": "select", "label": "Status", "width": 2, "options": ["Clean & sanitized", "Between-use care (scrape, wipe, re-grease)", "Not used today"], "required": true}, {"id": "notes", "type": "text", "label": "Notes", "width": 3}]}], "description": "For each machine used in today's production, confirm it was verified clean and sanitized per its SSOP and recorded on its own cleaning log, or mark \"Not used today\". Items without a separate log — the molds — are recorded here. Molds are scraped, wiped and re-greased between uses and washed weekly under SOP-906, so record which of those happened. Add or remove equipment as the line changes."}, {"id": "sanitizer", "title": "3. Detergent & Sanitizer Verification", "fields": [{"id": "detergent_used", "type": "text", "label": "Detergent used", "width": "third", "defaultValue": "Dawn Professional"}, {"id": "detergent_concentration", "help": "Per the manufacturer's instructions - Dawn Professional is 1-2 oz per 10 gallons of water", "type": "text", "label": "Detergent concentration", "width": "third", "required": true, "defaultValue": "1-2 oz per 10 gallons"}, {"id": "detergent_within_target", "type": "pass_fail", "label": "Detergent within target?", "width": "third", "required": true}, {"id": "detergent_test_method", "help": "How the dose was measured - pump strokes, measuring cup or proportioner. The Dawn Professional pump delivers 1 oz per full stroke.", "type": "text", "label": "Detergent test method", "width": "full", "defaultValue": "Measured dose per sink fill"}, {"id": "sanitizer_used", "type": "text", "label": "Sanitizer used", "width": "third", "defaultValue": "Noble Sani-512"}, {"id": "concentration_ppm", "type": "text", "label": "Concentration (PPM)", "width": "third", "required": true, "defaultValue": "200 ppm"}, {"id": "sanitizer_verified", "type": "pass_fail", "label": "Within target?", "width": "third", "required": true}, {"id": "test_method", "type": "text", "label": "Test method (e.g. test strip)", "width": "full", "defaultValue": "Test strip"}, {"id": "footbath_note", "text": "Foot baths — use the HIGH-RANGE quat strip. The baths run Sani-512 at 1:160, roughly three times the 1:512 food-contact strength. The 0-400 ppm strips used on equipment saturate at this concentration and will read high on a bath that has failed. Change the solution when the strip reads below target, when the bath is visibly soiled, or when it has been diluted by water carried in or by washdown.", "type": "info", "label": "Foot bath check"}, {"id": "footbath_check", "rows": {"mode": "fixed", "labels": ["Production entrance (from office / break room / reception)", "Walkthrough — production to inventory & packaging"], "addLabel": "Add foot bath", "deletable": true, "labelHeader": "Foot bath"}, "type": "grid", "label": "Foot baths — Sani-512 at 1:160", "columns": [{"id": "reading", "type": "text", "label": "Reading (ppm)", "width": 1}, {"id": "within_target", "type": "pass_fail", "label": "At strength?", "width": 1, "required": true}, {"id": "condition", "type": "pass_fail", "label": "Clean & not diluted?", "width": 1, "required": true}, {"id": "action", "type": "text", "label": "Action (none / recharged / changed)", "width": 2}]}], "description": "Confirm and record detergent and sanitizer concentration before use (SQF 11.2.5.3). Site chemicals: Dawn Professional detergent at 1-2 oz per 10 gallons of water; Noble Sani-512 sanitizer at the food-contact dilution of 1:512 (1 fl oz per 4 gallons, about 200 ppm quat)."}, {"id": "glass", "title": "4. Glass & Brittle Plastic Check", "fields": [{"id": "glass_check", "rows": {"mode": "fixed", "labels": ["Processing Room", "Processing Room", "Processing Room"], "addLabel": "Add item", "deletable": true, "labelHeader": "Location", "defaultValues": [{"item": "Pan scrubber dials"}, {"item": "Oven controls and door glass"}, {"item": "MIG thermometers"}]}, "type": "grid", "label": "Glass dial covers & MIG thermometers", "columns": [{"id": "item", "type": "text", "label": "Item", "width": 2}, {"id": "undamaged", "type": "pass_fail", "label": "Undamaged", "width": 1, "required": true}, {"id": "comments", "type": "text", "label": "Condition / comments", "width": 2}, {"id": "action", "type": "text", "label": "Action taken", "width": 2}]}], "description": "At the start of the shift, confirm glass instrument dial covers and MIG thermometers are undamaged (SQF 11.7.3.4). Mark Pass (undamaged), Fail (damaged/broken), or N/A. Any Fail requires a Glass Breakage Incident Report (FRM-908) and follows SOP-11.7.3. Items are drawn from the Glass & Brittle Plastic Register (FRM-907)."}, {"id": "operational_gmp", "title": "5. Operational GMP Check", "fields": [{"id": "gmp_check", "rows": {"mode": "fixed", "labels": ["Hair/beard nets worn; no exposed jewelry", "Clean outer garments; no eating/drinking/gum in production", "Handwash stations stocked (soap, towels, sanitizer)", "Hands washed on entry and as required", "Allergen controls / segregation followed", "Waste and floor debris controlled", "No condensation or drip over exposed product", "Pest control devices in place and intact", "Doors/screens to outside kept closed"], "addLabel": "Add check", "deletable": true, "labelHeader": "Check"}, "type": "grid", "label": "Operational GMP check", "columns": [{"id": "result", "type": "pass_fail", "label": "Conforms", "width": 1, "required": true}, {"id": "comments", "type": "text", "label": "Corrective action / comments", "width": 3}]}], "description": "During production, confirm operational GMPs are being followed. Mark Pass, Fail, or N/A; note corrective action for any Fail (absorbs the former FRM-904 Daily Operation Check)."}, {"id": "release", "title": "6. Corrective Actions & Release", "fields": [{"id": "all_corrected", "type": "pass_fail", "label": "All corrective actions completed before start-up", "width": "half", "required": true}, {"id": "released_by", "role": "filler", "type": "signature", "label": "SQF Practitioner (qualified inspector)", "width": "half", "required": true, "statement": "I inspected the area and equipment before start of production, verified the sanitizer concentration, and confirm the area is clean and released for production (or corrective action was completed as noted)."}, {"id": "supervisor", "role": "verifier", "type": "signature", "label": "Production Supervisor", "width": "half", "statement": "I confirm the pre-operation inspection was completed and the area is released for production."}], "description": "Production shall not begin until all non-conformances are corrected and the area is verified clean (SOP-11.2.12). A record of pre-operational hygiene inspection is maintained for a minimum of two years (SOP-2.2.3; SQF 11.2.5.9)."}], "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": false, "instanceTitleTemplate": "{inspection_date} — Daily Sanitation & Pre-Op Record"}, "schemaVersion": 1}, "revision_history": "v6 - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
       revision = 'v6'
 where id = '96b9eed2-3665-4857-a81c-b839d4f83f9d' and status = 'active' and revision = 'v6';
update public.sop_documents set content = $jx${"attachments": [{"name": "FRM-501_Formula_Sheet_Batch_Data.pdf", "path": "54f97a1b-8d3d-4b6b-98ce-5184aaf7d91e/files/FRM-501_Formula_Sheet_Batch_Data.pdf"}, {"name": "FRM-501_Formula_Sheet_Batch_Data.docx", "path": "54f97a1b-8d3d-4b6b-98ce-5184aaf7d91e/files/FRM-501_Formula_Sheet_Batch_Data.docx"}], "form_schema": {"sections": [{"id": "product_trial_information", "title": "Section 1 — Product & Trial Information", "fields": [{"id": "product_name", "type": "text", "label": "Product Name", "width": "third", "required": true, "showInList": true}, {"id": "made_as", "help": "Made on site for use in other products (the simple syrup): a batch of it is recorded on FRM-530, not on the Production Lot Record. Blank means a finished product.", "type": "select", "label": "Made as", "options": ["Finished product", "Made on site for use in other products"]}, {"id": "formula_version", "type": "text", "label": "Formula Version", "width": "third"}, {"id": "trial_prototype_no", "type": "text", "label": "Trial / Prototype No.", "width": "third"}, {"id": "date", "type": "date", "label": "Date", "width": "third"}, {"id": "developed_by", "type": "text", "label": "Developed By", "width": "third"}, {"id": "linked_product_request_no", "type": "text", "label": "Linked Product Request No.", "width": "third"}, {"id": "benchtop_batch_size", "type": "text", "label": "Benchtop Batch Size", "width": "third"}, {"id": "scaled_production_batch_size", "type": "text", "label": "Scaled / Production Batch Size", "width": "third"}, {"id": "allergens_in_formula", "type": "text", "label": "Allergens in Formula", "width": "third"}, {"id": "barcode_number", "help": "The number printed under the bar code on this product's pack, digits only. Leave blank if the pack carries no bar code.", "type": "text", "label": "Bar code number", "width": "third", "maxLength": 20}]}, {"id": "prototype_formulation", "title": "Section 2 — Prototype Formulation", "fields": [{"id": "prototype_formulation_grid", "rows": {"min": 1, "mode": "dynamic"}, "type": "grid", "label": "Prototype Formulation", "columns": [{"id": "ingredient", "type": "text", "label": "Ingredient", "pickFrom": {"fill": {"supplier": "manufacturer", "allergens": "allergens_contains"}, "form": "FRM-207", "field": "material_name", "filters": [{"op": "notEquals", "field": "status", "value": "Discontinued"}, {"op": "in", "field": "category", "values": ["Ingredient", "Additive / flavouring", "Processing aid"]}], "hintField": "manufacturer"}}, {"id": "supplier", "type": "text", "label": "Supplier"}, {"id": "added_at", "type": "select", "label": "Added at", "width": 1.3, "options": ["Mixing", "Dunking"], "scanFact": "none"}, {"id": "lot_batch_no", "type": "text", "label": "Lot / Batch #"}, {"id": "bakers_pct", "type": "number", "label": "Baker's %"}, {"id": "pct_of_formula", "type": "number", "label": "% of Formula", "shareOf": {"column": "production_qty", "nameColumn": "ingredient"}}, {"id": "benchtop_qty_g", "type": "number", "unit": "g", "label": "Benchtop Qty (g)"}, {"id": "production_qty", "type": "text", "label": "Production Qty"}, {"id": "allergens", "type": "text", "label": "Allergen(s)"}, {"id": "notes", "type": "text", "label": "Notes"}], "reorder": true, "scanLabel": true}]}, {"id": "process_parameters", "title": "Section 3 — Process Parameters (Benchtop vs Production)", "fields": [{"id": "process_parameters_grid", "rows": {"mode": "fixed", "labels": ["Mixing time", "Mixing speed", "Batter / Dough temperature", "Process / Bake temperature", "Process / Bake time", "Cooling / Set parameters", "Final moisture / Water activity (Aw)", "pH", "Net / Piece weight", "Yield (actual vs theoretical)"]}, "type": "grid", "label": "Process Parameters", "columns": [{"id": "target_spec", "type": "text", "label": "Target / Spec"}, {"id": "benchtop_actual", "type": "text", "label": "Benchtop Actual"}, {"id": "production_actual", "type": "text", "label": "Production Actual"}, {"id": "notes", "type": "text", "label": "Notes"}]}]}, {"id": "trial_sample_data_evaluation", "title": "Section 4 — Trial Sample Data & Evaluation", "fields": [{"id": "trial_sample_data_evaluation_info", "text": "Record sample/test results and sensory observations. Shelf-life trials shall be initiated for new products per SQF 2.3.1.3.", "type": "info", "label": "Instructions"}, {"id": "trial_sample_data_evaluation_area", "type": "textarea", "label": "Trial Sample Data & Evaluation"}]}, {"id": "validation_sign_off", "title": "Section 5 — Validation & Sign-off", "fields": [{"id": "validation_info", "text": "Formulation and process validated by facility trial and product testing (SQF 2.3.1.2).", "type": "info", "label": "Instructions"}, {"id": "facility_trial_conducted", "type": "checkbox", "label": "Facility trial conducted and benchtop formula successfully translated to production parameters."}, {"id": "trial_results_meet_spec", "type": "checkbox", "label": "Trial results meet the target product quality specification."}, {"id": "shelf_life_trial_initiated", "type": "checkbox", "label": "Shelf-life trial initiated / scheduled (SQF 2.3.1.3)."}, {"id": "developed_by_rd", "role": "filler", "type": "signature", "label": "Developed By (R&D)", "width": "half"}, {"id": "developed_by_rd_date", "type": "date", "label": "Date", "width": "half"}, {"id": "approved_by_quality_leader", "role": "verifier", "type": "signature", "label": "Approved By (SQF Practitioner)", "width": "half"}, {"id": "approved_by_quality_leader_date", "type": "date", "label": "Date", "width": "half"}]}], "settings": {"copyFrom": {"fields": ["made_as", "benchtop_batch_size", "scaled_production_batch_size", "prototype_formulation_grid", "process_parameters_grid"]}, "instanceTitleTemplate": "{product_name} {formula_version}"}, "schemaVersion": 1}, "revision_history": "New - 2026-10-29 - Role names and retention aligned to FSQM-004 and SOP-2.2.3 (readiness review). Labels and help text only; no revision change, so entries already made stay on this revision."}$jx$::jsonb,
